CREATE TABLE replica_events(seq BIGINT PRIMARY KEY,event_id VARCHAR(36) NOT NULL UNIQUE,kind VARCHAR(80) NOT NULL,payload LONGTEXT NOT NULL,created_at VARCHAR(40) NOT NULL,received_at VARCHAR(40) NOT NULL);
CREATE TABLE replica_state(id INT PRIMARY KEY CHECK(id=1),group_id VARCHAR(80),next_cursor BIGINT NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL,last_error VARCHAR(1000),last_sync_at VARCHAR(40),updated_at VARCHAR(40) NOT NULL);
INSERT INTO replica_state VALUES(1,NULL,0,'never',NULL,NULL,CURRENT_TIMESTAMP);
